1	// Shared helpers for the server tests: spawn server.mjs, send raw HTTP requests.
2	import { spawn } from 'node:child_process';
3	import http from 'node:http';
4	import fs from 'node:fs';
5	import os from 'node:os';
6	import path from 'node:path';
7	import { fileURLToPath } from 'node:url';
8	
9	export const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..', '..');
10	export const SERVER = path.join(ROOT, 'server.mjs');
11	const LISTEN_LINE = /^listening on http:\/\/127\.0\.0\.1:(\d+)\n$/;
12	
13	/** A fresh empty temp folder, removed with the returned cleanup. */
14	export function makeTempDir() {
15	  return fs.mkdtempSync(path.join(os.tmpdir(), 'rooms-test-'));
16	}
17	
18	/** process.env without PORT/DATA_FILE, then `env` applied (an undefined value removes the key). */
19	function buildEnv(env) {
20	  const base = { ...process.env };
21	  delete base.PORT;
22	  delete base.DATA_FILE;
23	  const merged = { ...base, ...env };
24	  return Object.fromEntries(Object.entries(merged).filter(([, v]) => v !== undefined));
25	}
26	
27	function spawnServer({ env = {}, cwd = ROOT } = {}) {
28	  const child = spawn(process.execPath, [SERVER], { cwd, env: buildEnv(env), stdio: ['ignore', 'pipe', 'pipe'] });
29	  const out = { stdout: '', stderr: '' };
30	  child.stdout.setEncoding('utf8').on('data', (d) => { out.stdout += d; });
31	  child.stderr.setEncoding('utf8').on('data', (d) => { out.stderr += d; });
32	  const exited = new Promise((resolve) => child.on('close', (code, signal) => resolve({ code, signal })));
33	  return { child, out, exited };
34	}
35	
36	/** Runs the server expecting it to exit by itself; resolves { code, stdout, stderr }. */
37	export async function runToExit({ env, cwd, timeoutMs = 5000 } = {}) {
38	  const { child, out, exited } = spawnServer({ env, cwd });
39	  const timer = setTimeout(() => child.kill('SIGKILL'), timeoutMs);
40	  const { code, signal } = await exited;
41	  clearTimeout(timer);
42	  return { code, signal, stdout: out.stdout, stderr: out.stderr };
43	}
44	
45	/**
46	 * Starts the server (PORT=0 unless given) and waits for its listening line.
47	 * Returns { port, child, stdout(), stderr(), stop() }; stop() kills it and resolves on exit.
48	 */
49	export async function startServer({ env = {}, cwd } = {}) {
50	  const { child, out, exited } = spawnServer({ env: { PORT: '0', ...env }, cwd });
51	  const port = await new Promise((resolve, reject) => {
52	    const timer = setTimeout(() => reject(new Error(`server did not start: ${out.stderr}`)), 5000);
53	    const onData = () => {
54	      const match = LISTEN_LINE.exec(out.stdout);
55	      if (match) {
56	        clearTimeout(timer);
57	        child.stdout.off('data', onData);
58	        resolve(Number(match[1]));
59	      }
60	    };
61	    child.stdout.on('data', onData);
62	    exited.then(({ code }) => {
63	      clearTimeout(timer);
64	      reject(new Error(`server exited early (code ${code}): ${out.stderr}`));
65	    });
66	  });
67	  return {
68	    port,
69	    child,
70	    stdout: () => out.stdout,
71	    stderr: () => out.stderr,
72	    exited,
73	    stop: async () => {
74	      if (child.exitCode === null && child.signalCode === null) child.kill('SIGTERM');
75	      return exited;
76	    },
77	  };
78	}
79	
80	/**
81	 * Sends one request with the request target written exactly as `target`.
82	 * `body` may be a string or Buffer. Resolves { status, headers, raw (Buffer), text, json }.
83	 * `json` is the parsed body, or undefined when the body is empty or not JSON.
84	 */
85	export function request(port, { method = 'GET', target = '/', headers = {}, body } = {}) {
86	  return new Promise((resolve, reject) => {
87	    const req = http.request({ host: '127.0.0.1', port, method, path: target, headers, agent: false });
88	    req.on('error', reject);
89	    req.on('response', (res) => {
90	      const chunks = [];
91	      res.on('data', (c) => chunks.push(c));
92	      res.on('error', reject);
93	      res.on('end', () => {
94	        const raw = Buffer.concat(chunks);
95	        const text = raw.toString('utf8');
96	        let json;
97	        try { json = JSON.parse(text); } catch { json = undefined; }
98	        resolve({ status: res.statusCode, headers: res.headers, raw, text, json });
99	      });
100	    });
101	    if (body !== undefined) req.write(body);
102	    req.end();
103	  });
104	}
105	
106	export const JSON_CT = 'application/json; charset=utf-8';
107	
108	/** POSTs a booking object as JSON with `Content-Type: application/json`. */
109	export function postBooking(port, booking, headers = { 'Content-Type': 'application/json' }) {
110	  return request(port, { method: 'POST', target: '/api/bookings', headers, body: JSON.stringify(booking) });
111	}
112	
113	/** A valid booking body; override fields as needed. */
114	export function booking(overrides = {}) {
115	  return { room: 'Aurora', title: 'Standup', date: '2026-11-03', start: '09:00', end: '10:00', ...overrides };
116	}
