  rejectCases('room', ['aurora', 'AURORA', ' Aurora', 'Aurora ', '', undefined, null, 1, ['Aurora'], 'Dawn'], ROOM_MSG);
  acceptCases('room', [['Aurora'], ['Borealis'], ['Cosmos']]);
});

